def decide(recipient_reputation: float, round_num: int, my_history: list[dict]) -> bool:
    # Base threshold that becomes stricter over time
    if round_num < 40:
        base = -0.2
    elif round_num < 80:
        base = 0.0
    else:
        base = 0.2

    # Adjust based on own last action (not partner action) to maintain a giving streak
    if my_history and my_history[-1].get('action') == 'donate':
        base -= 0.1          # more generous after donating
    else:
